WITH kept AS (SELECT s.* FROM orders s WHERE NOT EXISTS (SELECT 1 FROM payments ch WHERE ch.order_id = s.id AND ch.amount BETWEEN 990 AND 1320)) SELECT DATE_TRUNC('YEAR', order_date) AS year_start, CASE WHEN shipping_fee >= 32 THEN 'PREMIUM' ELSE 'STANDARD' END AS shipping_fee_tier, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles FROM kept GROUP BY year_start, shipping_fee_tier ORDER BY year_start DESC;
